import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int n = Integer.parseInt(st.nextToken());
        st.nextToken();
        String[] p = new String[n];
        for (int i = 0; i < n; i++) p[i] = st.nextToken();
        String s = st.nextToken();
        Arrays.sort(p);
        StringBuilder out = new StringBuilder();
        for (int i = 1; i <= s.length(); i++) {
            String prefix = s.substring(0, i);
            // First product >= prefix; matches are contiguous from there.
            int lo = 0, hi = n;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (p[mid].compareTo(prefix) < 0) lo = mid + 1; else hi = mid;
            }
            int taken = 0;
            for (int j = lo; j < n && p[j].startsWith(prefix) && taken < 3; j++, taken++) {
                if (taken > 0) out.append(' ');
                out.append(p[j]);
            }
            if (taken == 0) out.append('-');
            out.append('\n');
        }
        System.out.print(out);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strings"
)

func main() {
	rd := bufio.NewReader(os.Stdin)
	var n, m int
	fmt.Fscan(rd, &n, &m)
	p := make([]string, n)
	for i := range p {
		fmt.Fscan(rd, &p[i])
	}
	var s string
	fmt.Fscan(rd, &s)
	sort.Strings(p)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for i := 1; i <= len(s); i++ {
		prefix := s[:i]
		// First product >= prefix; matches are contiguous from there.
		j := sort.SearchStrings(p, prefix)
		var ans []string
		for ; j < n && strings.HasPrefix(p[j], prefix) && len(ans) < 3; j++ {
			ans = append(ans, p[j])
		}
		if len(ans) == 0 {
			fmt.Fprintln(w, "-")
		} else {
			fmt.Fprintln(w, strings.Join(ans, " "))
		}
	}
}
